import{_ as t,a,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const E=JSON.parse('{"title":"同一句《易》，为何有不同解释：历代注家对读","description":"以乾卦的元亨利贞、利见大人和九三为例，比较王弼、韩康伯、孔颖达、程颐、朱熹与《周易折中》的解释方法。","frontmatter":{"title":"同一句《易》，为何有不同解释：历代注家对读","description":"以乾卦的元亨利贞、利见大人和九三为例，比较王弼、韩康伯、孔颖达、程颐、朱熹与《周易折中》的解释方法。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"以乾卦的元亨利贞、利见大人和九三为例，比较王弼、韩康伯、孔颖达、程颐、朱熹与《周易折中》的解释方法。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings"},"next":{"text":"从经传到思想：时位、中正、变通、义利与生生","link":"/life/personal/yijing/philosophy"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings"},"next":{"text":"从经传到思想：时位、中正、变通、义利与生生","link":"/life/personal/yijing/philosophy"}},"headers":[],"relativePath":"life/personal/yijing/commentaries.md","filePath":"life/personal/yijing/commentaries.md"}'),n={name:"life/personal/yijing/commentaries.md"};function o(d,e,l,h,p,s){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="同一句《易》-为何有不同解释-历代注家对读" tabindex="-1">同一句《易》，为何有不同解释：历代注家对读 <a class="header-anchor" href="#同一句《易》-为何有不同解释-历代注家对读" aria-label="Permalink to &quot;同一句《易》，为何有不同解释：历代注家对读&quot;">​</a></h1><p>读注本最有收获的方式，是先固定一句经文，再看不同作者各增加了什么理由。只记“王弼重义理、朱熹重象数”这样的标签，容易错过真正的分歧：同一个“大人”究竟指谁，同一个“贞”属于什么语境，爻辞是在描写圣人的处境，还是在告诉占问者如何行动？</p><p>本文选取实际核读的乾卦与《系辞》片段，不以几个例子覆盖某位注家全部思想。先秦文本的作者问题见<a href="/life/personal/yijing/text-history">文本史</a>；这里的传统注家多有明确时代，但他们对更早作者的归属仍属于各自解释框架，不能不经论证就升级为历史事实。</p><h2 id="先把-注-疏-本义-集说-分开" tabindex="-1">先把“注”“疏”“本义”“集说”分开 <a class="header-anchor" href="#先把-注-疏-本义-集说-分开" aria-label="Permalink to &quot;先把“注”“疏”“本义”“集说”分开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文本或作者</th><th>时代与形式</th><th>本文重点观察什么</th></tr></thead><tbody><tr><td>王弼注</td><td>曹魏，解释经文及相关传文</td><td>一卦的主旨、爻的处境、时位之间的关联</td></tr><tr><td>韩康伯注</td><td>东晋，传世合本中承接《系辞》等部分</td><td>用较抽象的道、自然与变化概念说明传文</td></tr><tr><td>孔颖达等《正义》</td><td>唐代，经学疏释</td><td>展开旧注，处理异说、音义与论证</td></tr><tr><td>程颐《伊川易传》</td><td>北宋，逐卦阐释</td><td>天理、德行、政治与日常处事之间的贯通</td></tr><tr><td>朱熹《周易本义》</td><td>南宋，简明经传注解</td><td>象与占的语境，并区分经辞和传文的解释层次</td></tr><tr><td>《御纂周易折中》</td><td>清代，李光地等奉敕编纂</td><td>并列《本义》《程传》及诸说，再作取舍和会通</td></tr></tbody></table><p>《周易注疏》不是王弼一个人的书。四库本卷一题有王弼注、陆德明音义、孔颖达疏；到《系辞》卷十一、十二，题署为“晋韩伯注”。如果没有区分版面的“注”“疏”，就可能把唐人的长篇解释错归曹魏作者，或把韩康伯的意见误说成王弼之言。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%B3%A8%E7%96%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B701" target="_blank" rel="noopener noreferrer">卷一</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%B3%A8%E7%96%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B711" target="_blank" rel="noopener noreferrer">卷十一</a>。</p><h2 id="第一组对读-元亨利贞-究竟怎样分层" tabindex="-1">第一组对读：“元亨利贞”究竟怎样分层 <a class="header-anchor" href="#第一组对读-元亨利贞-究竟怎样分层" aria-label="Permalink to &quot;第一组对读：“元亨利贞”究竟怎样分层&quot;">​</a></h2><p>没有现代标点的四个字，提供了多种解释空间。先比较注家的说法，不急着宣布其中一家已经解决所有字源和文本年代问题。</p><h3 id="孔颖达与程颐-四德如何贯通天道与人事" tabindex="-1">孔颖达与程颐：四德如何贯通天道与人事 <a class="header-anchor" href="#孔颖达与程颐-四德如何贯通天道与人事" aria-label="Permalink to &quot;孔颖达与程颐：四德如何贯通天道与人事&quot;">​</a></h3><p>《正义》释乾卦，把元亨利贞作为乾之四德，分别联系元始、亨通、和利、贞正，并说明圣人怎样效法乾而生养万物、处理事务。这种解法连通卦辞、《彖》与《文言》，重点是形成可贯通的经典意义。</p><p>程颐在乾卦开头说，元是万物之始，亨是万物之长，利是万物之遂，贞是万物之成。他同时提醒，在其他卦里，这些字会“随事而变”。因此“程颐讲四德”不等于他认为所有卦出现“元”字都只能机械套用同一个解释。<a href="https://zh.wikisource.org/wiki/%E4%BC%8A%E5%B7%9D%E6%98%93%E5%82%B3" target="_blank" rel="noopener noreferrer">《伊川易传》卷一乾卦</a>。</p><h3 id="朱熹-先解释占辞-再读传文的展开" tabindex="-1">朱熹：先解释占辞，再读传文的展开 <a class="header-anchor" href="#朱熹-先解释占辞-再读传文的展开" aria-label="Permalink to &quot;朱熹：先解释占辞，再读传文的展开&quot;">​</a></h3><p>朱熹在卦辞下注，把元释为大、亨释为通、利释为宜、贞释为正而固；随即说明筮得此卦且六爻不变时，应如何理解其占。到了《彖》下，他又明确说这里把四字析为四德来阐发。这样一来，卦辞的占问功能和传文的哲学发展就能分别阅读。</p><p>这不是“朱熹完全不讲义理”。他仍把正固、德行以及天地生成纳入解释；区别在于，不能一开始就用后来的完整义理体系抹平原有占辞语境。他也认为经、传不同层次的意义能够并行，而非只能保留其中一层。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B71" target="_blank" rel="noopener noreferrer">《周易本义》卷一乾卦</a>。</p><h3 id="《折中》-承认两意-又说明四层" tabindex="-1">《折中》：承认两意，又说明四层 <a class="header-anchor" href="#《折中》-承认两意-又说明四层" aria-label="Permalink to &quot;《折中》：承认两意，又说明四层&quot;">​</a></h3><p>《周易折中》乾卦按语认可朱熹以占辞解释的方向，同时提出“虽只两意，实有四层”。它进一步追问：一时的通达和大的通达有什么不同？固守本身是否足够，还是先要合宜？这样就试图把占辞中的“大通、宜于正固”与传文的四德说明接起来。</p><p>这段很适合观察“折中”并不是把不同说法全部抄在一起。编者实际作了取舍，也提出了自己的会通论证。阅读时要把“本义”“程传”“某氏曰”和“案”分开，尤其不能把所引朱子语误署为李光地原创。<a href="https://www.shidianguji.com/zh/book/NGJ892412000002477155309/chapter/1lqq40825jf3c" target="_blank" rel="noopener noreferrer">《周易折中》乾卦相关段落</a>。</p><table tabindex="0"><thead><tr><th>同一问题</th><th>四德式解释重心</th><th>朱熹解释重心</th><th>《折中》的处理</th></tr></thead><tbody><tr><td>四字首先是什么</td><td>乾之德及生成次序</td><td>对占问者有条件的判断</td><td>先认可占辞的两意</td></tr><tr><td>人该如何行动</td><td>体仁、合礼、和义、贞固</td><td>通达仍须正固</td><td>合宜先于固守</td></tr><tr><td>经传如何关联</td><td>贯通为完整德性论</td><td>承认不同层次各有发明</td><td>用四层说明两者可相贯通</td></tr></tbody></table><p>这张表整理的是解释倾向，不是对先秦原义的最终裁决。例如把“贞”联系于早期占问语境，还涉及文字学和古代筮占材料；不能仅凭朱熹的“正固”二字就说所有问题已经结束。</p><h2 id="第二组对读-见龙在田-利见大人-——谁去见谁" tabindex="-1">第二组对读：“见龙在田，利见大人”——谁去见谁 <a class="header-anchor" href="#第二组对读-见龙在田-利见大人-——谁去见谁" aria-label="Permalink to &quot;第二组对读：“见龙在田，利见大人”——谁去见谁&quot;">​</a></h2><p>乾九二是检验读者是否真正理解注解的好例子。看到“利见大人”，不少人立即翻译成“去找一个贵人帮助我”。但注家关心的主客关系更复杂。</p><p>王弼说九二出潜离隐，德施周普，“虽非君位，君之德也”，并把乾卦中的二、五都与大人相联系。孔颖达进一步申说：九二虽然不在君位，却有君德，所以天下之人利于见到九二这样的大人；他还辨析把这里一律解释为九二去见九五的说法。这里的“大人”并非只等于职位最高的人。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%B3%A8%E7%96%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B701" target="_blank" rel="noopener noreferrer">《注疏》卷一九二</a>。</p><p>程颐的解释把九二之人置于德已显而位尚未至的处境，同时讨论有德之君与有德之臣相见、相辅的关系。解释的重点落在德与位怎样配合，不能只剩“攀附上级”这一种读法。<a href="https://zh.wikisource.org/wiki/%E4%BC%8A%E5%B7%9D%E6%98%93%E5%82%B3" target="_blank" rel="noopener noreferrer">《伊川易传》卷一九二</a>。</p><p>朱熹则特别把爻中所写之人与实际占问者分开：普通人占到此爻，可以理解为利于见到这样的有德之人；若自身已有相应的见龙之德，又可说利见九五在上之大人。他以主宾关系来解释为什么一句话能有不同落点。这不是随意改口，而是在明确谁具备经文描述的条件。</p><table tabindex="0"><thead><tr><th>阅读对象</th><th>不能跳过的问题</th><th>跳过后容易变成什么</th></tr></thead><tbody><tr><td>爻中之龙</td><td>它在什么位置，表现何种德？</td><td>神秘动物带来好运</td></tr><tr><td>“大人”</td><td>指爻中之人还是另一个有德者？</td><td>有钱有权的人</td></tr><tr><td>阅读者或占问者</td><td>是否具有文本设定的条件？</td><td>任何人自动获得同一承诺</td></tr></tbody></table><p>现代练习可以把这段转成“我缺少哪一种能够提供真实帮助的经验或能力”，却不能宣布某位熟人命定是自己的贵人。前者是反思，后者是未经证明的个人预测。</p><h2 id="第三组对读-九三为何既危险-又-无咎" tabindex="-1">第三组对读：九三为何既危险，又“无咎” <a class="header-anchor" href="#第三组对读-九三为何既危险-又-无咎" aria-label="Permalink to &quot;第三组对读：九三为何既危险，又“无咎”&quot;">​</a></h2><p>乾九三：“君子终日乾乾，夕惕若，厉无咎。”标点在不同版本中可能略异，但勤勉、警惕、危险与免咎之间的张力很清楚。</p><p>王弼注把九三放在下体之极、上体之下的位置：它已有向上的职责，却还不能安于尊位；只按下位要求行事会废其上进之德，只按上位行事又可能失去处下之礼。危险由处境结构产生，不只是这个人不够努力。孔颖达疏再把“能如此戒慎”作为无咎的条件，明确指出不是任何行动都能免咎。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%B3%A8%E7%96%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B701" target="_blank" rel="noopener noreferrer">《注疏》卷一九三</a>。</p><p>朱熹在此同样强调重刚不中、居下之上的危地，并把“君子”落实到占者：能够保持相应忧惧，才可在危险中免咎。程颐则从修德、处上下之际及随时戒惕展开。三个文本的侧重点不同，但都不支持“努力一定成功”的无条件口号。</p><p>用工作场景作类比：一个人已承担项目协调，却没有全部授权。九三可以提醒他补齐确认机制、清楚说明职责、识别越权风险。若把“终日乾乾”理解成无限加班，反而忽略了注家真正讨论的角色与时位问题。现代类比是否成立，还应由实际授权和沟通证据判断。</p><h2 id="韩康伯应该放在什么位置" tabindex="-1">韩康伯应该放在什么位置 <a class="header-anchor" href="#韩康伯应该放在什么位置" aria-label="Permalink to &quot;韩康伯应该放在什么位置&quot;">​</a></h2><p>韩康伯不是给王弼乾卦注加几句补充的作者。传世注疏的《系辞》等部分保存了他的注，这一分工应先从卷首题署核对。</p><p>例如《系辞下》说“天地之大德曰生”，韩注从施生而不为的角度解释；说“何以聚人曰财”，韩注指出财所以资助物的生存。前者有自然、无为的理论色彩，后者又没有绕开维持生活的现实条件。这比“魏晋注家只谈空无”的概括具体得多。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%B3%A8%E7%96%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B712" target="_blank" rel="noopener noreferrer">《周易注疏》卷十二开篇</a>。</p><p>阅读韩注，可以先找他怎样解释抽象词，再看孔疏怎样补充举例和人事说明。尤其注意孔疏并不只是冗长重复，有时会展示不同分章方案、批评某种强行区分，保留注释传统内部的辩论。</p><h2 id="怎样选一个适合当前问题的注本" tabindex="-1">怎样选一个适合当前问题的注本 <a class="header-anchor" href="#怎样选一个适合当前问题的注本" aria-label="Permalink to &quot;怎样选一个适合当前问题的注本&quot;">​</a></h2><p>初读卦爻辞，可先用简明注本认字、辨句、分清经传；遇到某个字或主客关系不明，再查《注疏》。想研究修养与治理怎样从卦爻展开，可连续读《程传》；想研究象、占与义理的分层，可对照《本义》；想比较多家意见，可读《折中》，但要始终追踪每句话的署名。</p><p>不要把这些次序理解为“越晚越正确”或“越早越纯粹”。早的注本可能离某些旧传统更近，也可能受其时代问题引导；晚的汇编可保存已难寻的材料，也可能通过取舍造成新的偏向。判断一段注释，应看它能否解释具体字句、能否处理反例，以及是否坦白增加了经文没有明说的前提。</p><h2 id="一张可反复使用的对读卡" tabindex="-1">一张可反复使用的对读卡 <a class="header-anchor" href="#一张可反复使用的对读卡" aria-label="Permalink to &quot;一张可反复使用的对读卡&quot;">​</a></h2><p>每次只比较一条辞：抄原文；列两家释义；分别写出其证据；指出共同点；说明分歧究竟在字义、人物所指、时位、筮法还是价值判断；最后把自己的现代应用另列一栏。若还不能判断，保留两个解释，比写“各有道理”更有价值。</p><p>本篇实际核读《注疏》卷一乾九二、九三，卷十一题疏与卷十二开篇，《程传》乾卦，《本义》卷一乾卦，以及《折中》乾卦相关集说和按语。识典该页网页标题与正文卷题不一致，引用按正文“御纂周易折中卷第一”及乾卦定位，未以网页标题代替古籍卷次。下一步可用<a href="/life/personal/yijing/reading-practice">六卦对读练习</a>亲自做一张卡，再读<a href="/life/personal/yijing/philosophy">经传中的思想问题</a>。<a href="/life/personal/yijing/overview">返回易经专题</a>。</p>',41)])])}const f=t(n,[["render",o]]);export{E as __pageData,f as default};
